/bin/bash -lc "cd /workspace && python3 - <<'PY'
import gzip,csv,re,requests,json,time,os,pickle
cache='encff_to_exp.json'
if os.path.exists(cache):
    enc_to_exp=json.load(open(cache))
else:
    with gzip.open('borzoi_targets_human.txt.gz','rt') as f: rows=list(csv.reader(f, delimiter='\\t'))[1:]
    encs=sorted(set(re.sub(r'[+-]"'$'"','',r[1]) for r in rows if r[1].startswith('ENCFF')))
    enc_to_exp={}
    chunk_size=100
    for i in range(0,len(encs),chunk_size):
        chunk=encs[i:i+chunk_size]
        params=[('type','File')]
        for a in chunk: params.append(('accession',a))
        params += [('limit','all'),('format','json')]
        for attempt in range(3):
            try:
                r=requests.get('https://www.encodeproject.org/search/',params=params,timeout=120)
                j=r.json(); got=j.get('@graph',[])
                for f in got:
                    enc_to_exp[f['accession']]=f.get('dataset')
                break
            except Exception as e:
                print('retry file',i,e); time.sleep(3)
        if i%500==0: print('files',i+len(chunk),len(enc_to_exp))
    print('mapped files',len(enc_to_exp),'of',len(encs))
    json.dump(enc_to_exp,open(cache,'w'))
# get unique experiments
exps=sorted(set(enc_to_exp.values()))
print('unique exps',len(exps))
# query experiment batch by accession (path /experiments/ENCSR/)
exp_cache='exp_to_gsm.json'
if os.path.exists(exp_cache):
    exp_to_gsm=json.load(open(exp_cache))
else:
    exp_to_gsm={}
    # ENCODE search experiments with accession repeated
    chunk_size=100
    accs=sorted(set(x.split('/')[-2] for x in exps))
    print('experiment accessions',len(accs))
    for i in range(0,len(accs),chunk_size):
        chunk=accs[i:i+chunk_size]
        params=[('type','Experiment')]
        for a in chunk: params.append(('accession',a))
        params += [('limit','all'),('format','json')]
        for attempt in range(3):
            try:
                r=requests.get('https://www.encodeproject.org/search/',params=params,timeout=120)
                j=r.json(); got=j.get('@graph',[])
                for e in got:
                    gsms=[]
                    for x in e.get('dbxrefs',[]):
                        if x.startswith('GEO:'):
                            gsms.append(x[4:])
                    exp_to_gsm[e['accession']]=gsms
                break
            except Exception as e:
                print('retry exp',i,e); time.sleep(3)
        if i%500==0: print('exps',i+len(chunk),len(exp_to_gsm))
    json.dump(exp_to_gsm,open(exp_cache,'w'))
print('mapped exps',len(exp_to_gsm))
# For each Borzoi track, derive set of possible GSM source IDs
with gzip.open('borzoi_targets_human.txt.gz','rt') as f: rows=list(csv.reader(f, delimiter='\\t'))[1:]
borzoi_gsms=set()
missing=set()
for r in rows:
    ident=r[1]
    if ident.startswith('GSM'):
        borzoi_gsms.add(ident)
    elif ident.startswith('ENCFF'):
        clean=re.sub(r'[+-]"'$'"','',ident)
        exp=enc_to_exp.get(clean)
        if exp:
            acc=exp.split('/')[-2]
            gs=exp_to_gsm.get(acc,[])
            if gs: borzoi_gsms.update(gs)
            else: missing.add(acc)
        else: missing.add(clean)
print('borzoi source GSM set',len(borzoi_gsms),'missing exp/noGSM',len(missing))
# load Sei mapping
mapf={}
for line in open('sei_cistrome_to_gsm.tsv').read().splitlines()[1:]:
    cid,g=line.split('\\t'); mapf[cid]=g
matches=[(cid,g) for cid,g in mapf.items() if g in borzoi_gsms]
print('Sei cistrome tracks matching Borzoi source GSM',len(matches))
print(matches[:20])
PY"

